#include "fractal/intent_replay.h"
#include <string.h>
void fractal_replay_cache_init(fractal_replay_cache*c,uint64_t first){if(c){memset(c,0,sizeof(*c));c->first_retained_sequence=first;}}
fractal_replay_result fractal_replay_cache_apply(fractal_replay_cache*c,const fractal_client_intent*i,uint64_t payload,fractal_workspace_transition tr){fractal_replay_result r={FRACTAL_REPLAY_CAPACITY_EXHAUSTED,tr};uint32_t n;if(!c||!i)return r;if(i->command_sequence<c->first_retained_sequence){r.kind=FRACTAL_REPLAY_HISTORY_EXPIRED;return r;}for(n=0;n<c->count;n++){fractal_replay_record*e=&c->records[n];if(e->occupied&&fractal_workspace_id_equal(e->participant_id,i->participant_id)&&e->command_sequence==i->command_sequence){if(fractal_workspace_id_equal(e->intent_identity,i->identity)&&e->payload_identity==payload){r.kind=FRACTAL_REPLAY_IDENTICAL_RESULT;r.transition=e->transition;}else r.kind=FRACTAL_COMMAND_SEQUENCE_CONFLICT;return r;}}
if(c->count<FRACTAL_REPLAY_CACHE_CAPACITY){fractal_replay_record*e=&c->records[c->count++];e->participant_id=i->participant_id;e->command_sequence=i->command_sequence;e->intent_identity=i->identity;e->payload_identity=payload;e->transition=tr;e->occupied=true;r.kind=FRACTAL_REPLAY_NEW_ACCEPTED;return r;}return r;}
